def atomic_json(path: Path, value: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True); fd, tmp = tempfile.mkstemp(prefix=f".{path.name}.", dir=str(path.parent))
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as f: json.dump(value, f, indent=2, sort_keys=True); f.write("\n"); f.flush(); os.fsync(f.fileno())
        os.replace(tmp, path)
    finally:
        if os.path.exists(tmp): os.unlink(tmp)


def sha256(path: Path) -> str:
    h = hashlib.sha256()
    with path.open("rb") as f:
        for c in iter(lambda: f.read(1 << 20), b""): h.update(c)
    return h.hexdigest()


def read_json(path: Path) -> Any:
    return json.loads(path.read_text(encoding="utf-8"))


def cmd(text: str) -> str:
    try: return subprocess.check_output(text, shell=True, text=True, stderr=subprocess.STDOUT, timeout=20)
    except Exception as e: return f"command failed: {e}"


def prefix_table(metrics: dict[str, Any], conditions: list[str]) -> list[str]:
    lines = ["| condition | p1 | p2 | p4 | p8 | p16 | source@16 | target@16 | category@16 | video@16 |", "|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|"]
    for c in conditions:
        d = metrics["conditions"][c]; vals = [x["ceiling_correct"] for x in d["prefix_summary"]]; p = d["prefix16"]; lines.append(f"| {c} | " + " | ".join(f"{v}/76" for v in vals) + f" | {p['source_reliable_events']} | {p['target_reliable_events']} | {p['category_coverage']} | {p['video_coverage']} |")
    return lines


def main() -> None:
    stage0 = read_json(OUT / "audit/failure_taxonomy_summary.json"); stage0_rep = read_json(OUT / "audit/phase24_reproduction.json"); stage1 = read_json(OUT / "metrics/stage1_unified_strategies.json"); stage3 = read_json(OUT / "metrics/stage3_proposal_validation.json"); mot = read_json(OUT / "audit/mot_compatibility.json"); stage3_records = read_json(OUT / "audit/stage3_attention_event_records.json")["records"]
