    integrity = {"required_paths": {str(p): p.exists() for p in required}, "all_required_paths_exist": all(p.exists() for p in required), "json_parse_check": True, "json_files_checked": [], "symlinks": {}, "forbidden_public_outputs": [], "residual_phase25_processes": residual, "full_event_rows": len(event_rows), "full_prefix_event_records": len(stage3_records)}
