    decision = {"protocol": "trackocd_iclr27_phase25_mot_preserving_proposal_generalization", "execution_time": dt.datetime.now(dt.timezone.utc).isoformat(), "decision_code": "P25_GATE_P2_PARTIAL_STOP_BEFORE_CORRESPONDENCE", "gate_p2": stage3["gate_p2"], "phase24_frozen": {"raw_prefix16": 25, "candidate_pool_oracle_prefix16": 38, "setaware_top20_prefix16": 32, "source_target_raw": [49, 40], "source_target_setaware": [56, 46], "fold_raw": [8, 2, 10, 5], "fold_setaware": [7, 1, 15, 9], "gate": "P24_GATE_P2_PARTIAL"}, "stage0": {"reproduction": stage0_rep, "summary": stage0, "taxonomy_path": str(OUT / "audit/failure_taxonomy_76.json"), "fold_shift_path": str(OUT / "audit/fold_shift_report.json")}, "stage1": {"metrics": str(OUT / "metrics/stage1_unified_strategies.json"), "best_real": stage1["stage2_authorization"], "mot_compatibility": mot}, "stage2": {"branch": "attention_set_selector", "architecture": "one two-head self-attention block over key-aligned DINOv2 CLS/ROI+causal geometry; quality and uncertainty heads", "loss": "IoU-soft listwise + 0.50 quality + 0.25 same-row hard-negative + 0.10 uncertainty", "steps": 4000, "batch_size": 32, "checkpoint_every": 500, "amp": "bf16", "folds": fold_metrics, "source_branch": "not launched; candidate pool oracle met 38/76", "forbidden_inputs": ["GT", "row IoU", "category/physical/semantic ID", "text", "future frames/tracks", "StateMemory"]}, "stage3": {"metrics": str(OUT / "metrics/stage3_proposal_validation.json"), "best_condition": p16_best, "prefix16": best_d}, "resources": {"launch_preflight": {"available_ram_gib": 99, "total_ram_gib": 125, "physical_gpus": [4, 5, 6, 7], "gpu0_3_external_untouched": True, "data1_free_gib": 21, "worker_count": 4}, "postflight": str(OUT / "audit/resource_postflight.json"), "no_oom": True, "external_processes_touched": False, "supervisor_pid": 37538, "worker_pids": [37553, 37554, 37555, 37556]}, "incidents": [{"type": "stage1_syntax", "root_cause": "confidence fallback bracket typo", "action": "minimal syntax repair and full rerun", "impact": "no artifact written"}, {"type": "stage1_condition_dispatch", "root_cause": "top-K condition returned through fallthrough", "action": "minimal dispatch return repair and full rerun", "impact": "no artifact written"}, {"type": "stage1_fallback_index", "root_cause": "raw fallback array concatenation used invalid index", "action": "explicit raw-preserving sort repair and full rerun", "impact": "no artifact written"}, {"type": "stage2_smoke", "root_cause": "Phase25 GEOM_FIELDS omitted box_y2_norm (21 vs 22 dims)", "action": "add field and rebuild Phase25 manifests; Phase24 untouched", "impact": "first smoke marker retained without done/checkpoint"}, {"type": "bounded_training", "root_cause": "none", "action": "supervisor completed naturally on explicit physical GPUs 4--7", "impact": "no OOM, no external termination"}], "public_q1": {"accessed": False, "sealed": True, "sealed_names": ["DEV+", "Q1", "public new-model labels"]}, "correspondence_controller_backbone": {"correspondence": False, "controller": False, "StateMemory": False, "threshold_sweep": False, "modern_backbone_download": False, "public_evaluation": False}, "integrity": integrity, "artifact_hashes": {str(p): sha256(p) for p in required if p.exists()}, "next_direction": "Gate P2 is PARTIAL; do not enter correspondence/controller/backbone. Establish proposal-source/domain generalization or revise the task protocol before any semantic correspondence experiment."}
