        p = stage3["conditions"][c]["prefix16"]; lines.append(f"| {c} | " + " / ".join(f"{x['ceiling_correct']}" for x in p["by_fold"]) + f" | {p['source_reliable_events']} | {p['target_reliable_events']} | {p['category_coverage']} | {p['video_coverage']} |")
